void Draw(ImGuiTestContext* ctx){auto& s=ctx->GetVars<Fixture>();if(!s.refresh)s.Init();if(s.lock){s.locked=s.recovery->Protect(s.state.documents,"coin-fixture-password-123") && sh::RequestPrivacyLock(s.state,s);s.lock=false;}if(s.recovery->Locked())s.refresh->PrivacyLock();if(s.refresh_now){s.refresh->RequestNow(0);s.refresh_now=false;}s.refresh->Tick(0);if(s.conflict){auto scope=a::HistoryMetadataScope(*s.state.documents.Find(1)->binding);auto old=s.recovery->HistoryMetadata(scope);s.recovery->SaveOutputLabel(scope,{H('1'),0},"Other scoped writer",old.value->revision);s.conflict=false;}if(s.recovery_conflict){const bool enabled=s.recovery->Enable(s.state.documents);auto store=storage::MetadataStore::Open(s.scratch/"metadata.sqlite");if(enabled && store){auto record=(*store.value)->LoadRecovery();if(record)s.recovery_conflict_done=bool((*store.value)->SaveRecovery(*record.value));}s.recovery_conflict=false;}ui::components::NativeInputScope native(&s.files);const auto theme=ui::MakeBootstrapTheme({});ui::theme::Scope style(theme);s.facts=sh::DrawWorkspace(s.state,s,theme,{},ImVec2{1280,800});s.ready=s.facts.coin_order.size()==12;if(auto* d=s.state.documents.Find(1)){auto loaded=s.recovery->HistoryMetadata(a::HistoryMetadataScope(*d->binding));if(loaded){s.revision=loaded.value->revision;s.saved_freezes=loaded.value->freezes;s.saved.clear();for(const auto& l:loaded.value->labels)if(l.target.kind==storage::TargetKind::Output)s.saved[l.target.key]=l.text;}}if(s.recovery_conflict_done && !s.recovery->Locked()){auto store=storage::MetadataStore::Open(s.scratch/"metadata.sqlite");if(store){auto record=(*store.value)->LoadRecovery();if(record)s.recovery_revision=record.value->revision;}}if(auto* d=s.state.documents.Find(2);d && d->binding){auto loaded=s.recovery->HistoryMetadata(a::HistoryMetadataScope(*d->binding));if(loaded)s.other_revision=loaded.value->revision;}}
void Ready(ImGuiTestContext* ctx,Fixture& s){ctx->SetRef("###workspace");for(int n=0;n<40 && !s.ready;++n){std::this_thread::sleep_for(std::chrono::milliseconds(1));ctx->Yield();}ctx->Yield(3);}
ImGuiTest* Test(ImGuiTestEngine* e,const char* name){auto* t=IM_REGISTER_TEST(e,"roots.coins",name);t->SetVarsDataType<Fixture>();t->GuiFunc=Draw;return t;}
void Press(ImGuiTestContext* ctx,Fixture& s,const char* key){ctx->ItemNavActivate(s.facts.coin.at(key).id);ctx->Yield(3);}
void ConfirmClear(ImGuiTestContext* ctx,Fixture& s)
{
    Press(ctx,s,"clear-pinned-draft");
    ctx->ItemClick(s.facts.document_actions.at("confirm-clear-send").id);
    ctx->Yield(3);
}
