void RegisterCoinTests(ImGuiTestEngine* e){
    auto* t=Test(e,"stable_multiselect_sort_refresh_disappearance_and_other");t->TestFunc=[](ImGuiTestContext* ctx){auto& s=ctx->GetVars<Fixture>();Ready(ctx,s);IM_CHECK(s.ready);ctx->ItemClick(s.facts.coin.at("row-"+K(11)).id);ctx->ItemClick(s.facts.coin.at("row-"+K(10)).id);ctx->Yield(3);const auto selected=s.state.documents.Find(1)->coins.Selection();IM_CHECK_EQ(selected.size(),2);Press(ctx,s,"sort-value");IM_CHECK_EQ(s.facts.coin_order.front(),K(0));IM_CHECK_EQ(s.state.documents.Find(1)->coins.Selection(),selected);s.phase=2;s.refresh_now=true;for(int n=0;n<40 && (s.calls<2 || s.refresh->Busy());++n){std::this_thread::sleep_for(std::chrono::milliseconds(1));ctx->Yield();}ctx->Yield(3);IM_CHECK_EQ(s.state.documents.Find(1)->coins.Selection(),selected);const auto& inventory=*s.state.coins.at(1).inventory;IM_CHECK(!inventory.Rows().at(K(11)).present);IM_CHECK_EQ(inventory.Rows().size(),12);IM_CHECK(inventory.Rows().at(K(10)).eligible==false);IM_CHECK(inventory.Rows().at(K(10)).reason.find("unsafe")!=std::string::npos);IM_CHECK_EQ(inventory.Summary(selected).selected_value->sats(),230000002);s.state.coins.at(1).chart_group=9;ctx->Yield(3);const auto chart=*inventory.Chart();IM_CHECK_EQ(chart.size(),10);IM_CHECK_EQ(chart.back().keys.size(),2);const auto rect=s.facts.coin.at("chart").rect;ctx->MouseMoveToPos({rect[0]+(rect[2]-rect[0])*.95F,(rect[1]+rect[3])*.5F});ctx->MouseClick(0);ctx->Yield(3);for(const auto& key:chart.back().keys)IM_CHECK(s.state.documents.Find(1)->coins.Selection().contains(key));Press(ctx,s,"toggle-group");for(const auto& key:chart.back().keys)IM_CHECK(!s.state.documents.Find(1)->coins.Selection().contains(key));Press(ctx,s,"toggle-group");for(const auto& key:chart.back().keys)IM_CHECK(s.state.documents.Find(1)->coins.Selection().contains(key));IM_CHECK(s.state.documents.Find(1)->selected_coins.empty());IM_CHECK(s.state.presentation.Tree().Validate());};
    t=Test(e,"labels_enter_focus_loss_conflict_and_deliberate_retry");t->TestFunc=[](ImGuiTestContext* ctx){auto& s=ctx->GetVars<Fixture>();Ready(ctx,s);ctx->ItemClick(s.facts.coin.at("row-"+K(11)).id);ctx->Yield(2);ctx->ItemInputValue(s.facts.coin.at("label-"+K(11)).id,"Acknowledged coin");ctx->Yield(2);IM_CHECK_EQ(s.saved.at(K(11)),"Acknowledged coin");IM_CHECK_EQ(s.revision,1);ctx->ItemClick(s.facts.coin.at("label-"+K(11)).id);ctx->KeyPress(ImGuiMod_Ctrl|ImGuiKey_A);ctx->KeyChars("Focus loss saved");ctx->Yield(2);ctx->ItemClick(s.facts.coin.at("sort-value").id);ctx->Yield(3);IM_CHECK_EQ(s.saved.at(K(11)),"Focus loss saved");IM_CHECK_EQ(s.revision,2);ctx->ItemClick(s.facts.coin.at("label-"+K(11)).id);ctx->KeyPress(ImGuiMod_Ctrl|ImGuiKey_A);ctx->KeyChars("Row focus saved");ctx->Yield(2);ctx->ItemClick(s.facts.coin.at("row-"+K(10)).id);ctx->Yield(3);IM_CHECK_EQ(s.saved.at(K(11)),"Row focus saved");IM_CHECK_EQ(s.revision,3);ctx->ItemClick(s.facts.coin.at("row-"+K(11)).id);ctx->Yield(3);s.conflict=true;ctx->Yield(2);ctx->ItemClick(s.facts.coin.at("label-"+K(11)).id);ctx->KeyPress(ImGuiMod_Ctrl|ImGuiKey_A);ctx->KeyChars("Unacknowledged coin draft");ctx->Yield(2);ctx->ItemClick(s.facts.coin.at("sort-date").id);ctx->Yield(3);const auto& draft=s.state.documents.Find(1)->coins.drafts.at(K(11));IM_CHECK_EQ(draft.draft,"Unacknowledged coin draft");IM_CHECK_EQ(draft.saved,"Row focus saved");IM_CHECK(!draft.error.empty());IM_CHECK(s.state.presentation.Snapshot().find("Coin label was not saved")!=std::string::npos);ctx->Yield(15);IM_CHECK_EQ(s.revision,4);Press(ctx,s,"reload-labels");ctx->Yield(10);IM_CHECK_EQ(s.revision,4);ctx->ItemInputValue(s.facts.coin.at("label-"+K(11)).id,"Deliberate retry");ctx->Yield(3);IM_CHECK_EQ(s.saved.at(K(11)),"Deliberate retry");IM_CHECK_EQ(s.revision,5);};
    t=Test(e,"csv_exact_new_file_retirement_and_hidden_amounts");t->TestFunc=[](ImGuiTestContext* ctx){auto& s=ctx->GetVars<Fixture>();Ready(ctx,s);ctx->ItemClick(s.facts.coin.at("row-"+K(11)).id);ctx->Yield(2);ctx->ItemInputValue(s.facts.coin.at("label-"+K(11)).id,"=public,\"quoted\"");ctx->Yield(2);Press(ctx,s,"csv");std::ifstream file(s.files.destination);std::string bytes((std::istreambuf_iterator<char>(file)),{});IM_CHECK(bytes.find("\"1.20000001\"")!=std::string::npos);IM_CHECK(bytes.find("\"'=public,\"\"quoted\"\"\"")!=std::string::npos);Press(ctx,s,"csv");std::ifstream original(s.files.destination);IM_CHECK_EQ(std::string((std::istreambuf_iterator<char>(original)),{}),bytes);s.files.destination=(s.scratch/"retired.csv").string();s.files.hold=true;Press(ctx,s,"csv");s.state.privacy.hidden=true;ctx->Yield(3);s.files.hold=false;ctx->Yield(3);IM_CHECK(!std::filesystem::exists(s.files.destination));IM_CHECK(s.facts.coin.at("csv").disabled && s.facts.coin.at("sort-value").disabled);IM_CHECK(s.state.presentation.ChartSamples().empty());IM_CHECK(s.state.presentation.Snapshot().find("1.20000001")==std::string::npos);IM_CHECK(s.state.presentation.Snapshot().find("public,\"quoted\"")==std::string::npos);};
    t=Test(e,"label_wallet_query_privacy_and_encrypted_lock_fences");t->TestFunc=[](ImGuiTestContext* ctx){auto& s=ctx->GetVars<Fixture>();Ready(ctx,s);ctx->ItemClick(s.facts.coin.at("row-"+K(11)).id);ctx->Yield(2);ctx->ItemClick(s.facts.coin.at("label-"+K(11)).id);ctx->KeyPress(ImGuiMod_Ctrl|ImGuiKey_A);ctx->KeyChars("Retained private-view draft");ctx->Yield(2);s.state.privacy.hidden=true;ctx->Yield(3);IM_CHECK_EQ(s.revision,0);IM_CHECK_EQ(s.state.documents.Find(1)->coins.drafts.at(K(11)).draft,"Retained private-view draft");s.state.privacy.hidden=false;ctx->Yield(3);ctx->ItemClick(s.facts.coin.at("label-"+K(11)).id);ctx->KeyPress(ImGuiMod_Ctrl|ImGuiKey_A);ctx->KeyChars("Retained wallet draft");ctx->Yield(2);auto binding=*s.state.documents.Find(1)->binding;binding.wallet=*WalletId::Make("other fixture wallet");auto other=s.state.documents.OpenWallet("Other wallet",binding,true);s.state.documents.Find(other)->history.enabled=true;ctx->Yield(3);IM_CHECK_EQ(s.revision,0);IM_CHECK_EQ(s.other_revision,0);IM_CHECK_EQ(s.state.documents.Find(1)->coins.drafts.at(K(11)).draft,"Retained wallet draft");s.state.documents.Activate(1);ctx->Yield(3);ctx->ItemClick(s.facts.coin.at("label-"+K(11)).id);ctx->KeyPress(ImGuiMod_Ctrl|ImGuiKey_A);ctx->KeyChars("Retained query draft");ctx->Yield(2);s.state.documents.Find(1)->history.query_revision++;ctx->Yield(3);IM_CHECK_EQ(s.revision,0);s.state.documents.Find(1)->history.query_revision--;ctx->Yield(3);s.lock=true;ctx->Yield(3);IM_CHECK(s.locked && s.recovery->Locked() && s.state.coins.empty() && s.state.documents.Documents().empty());IM_CHECK(s.state.presentation.Snapshot().find("public-address")==std::string::npos);};
}

void RegisterCoinControlTests(ImGuiTestEngine* e){
    const auto make=[&](const char* name){auto* t=IM_REGISTER_TEST(e,"roots.coin-controls",name);t->SetVarsDataType<Fixture>();t->GuiFunc=Draw;return t;};
    auto* t=make("outpoint_context_cas_retry_and_clear_any_selection");t->TestFunc=[](ImGuiTestContext* ctx){auto& s=ctx->GetVars<Fixture>();Ready(ctx,s);const auto point=K(11);const auto popup=[&]{const auto rect=s.facts.coin.at("row-"+point).rect;ctx->MouseMoveToPos({(rect[0]+rect[2])/2,(rect[1]+rect[3])/2});ctx->MouseClick(1);ctx->Yield(3);};popup();Press(ctx,s,"freeze");IM_CHECK_EQ(s.saved_freezes.size(),1);IM_CHECK(s.saved_freezes[0].key==point);IM_CHECK(s.state.coins.at(1).inventory->Rows().at(point).eligible==false);IM_CHECK(s.state.presentation.Tree().Validate());s.conflict=true;ctx->Yield(2);Press(ctx,s,"unfreeze");IM_CHECK_EQ(s.saved_freezes.size(),1);IM_CHECK(s.state.presentation.Snapshot().find("not acknowledged")!=std::string::npos);const auto revision=s.revision;ctx->Yield(15);IM_CHECK_EQ(s.revision,revision);Press(ctx,s,"reload-policy");ctx->Yield(10);IM_CHECK_EQ(s.revision,revision);Press(ctx,s,"unfreeze");IM_CHECK(s.saved_freezes.empty());ctx->KeyPress(ImGuiKey_Escape);ctx->Yield(3);s.state.documents.Find(1)->coins.ReplaceSelection({H('e').hex()+":99",point});s.state.privacy.hidden=true;ctx->Yield(3);IM_CHECK(!s.facts.coin.at("clear-selection").disabled);Press(ctx,s,"clear-selection");IM_CHECK(s.state.documents.Find(1)->coins.Selection().empty());s.state.privacy.hidden=false;ctx->Yield(3);Press(ctx,s,"select-all");IM_CHECK_EQ(s.state.documents.Find(1)->coins.Selection().size(),12);};
    t=make("send_exact_fresh_reservation_collision_release_and_clear");t->TestFunc=[](ImGuiTestContext* ctx){auto& s=ctx->GetVars<Fixture>();Ready(ctx,s);ctx->ItemClick(s.facts.coin.at("row-"+K(11)).id);ctx->ItemClick(s.facts.coin.at("row-"+K(10)).id);ctx->Yield(3);const auto pins=s.state.documents.Find(1)->coins.Selection();Press(ctx,s,"send-selected");const auto first=s.state.documents.ActiveId();IM_CHECK(first==2 && s.state.documents.Find(first)->coin_draft);IM_CHECK_EQ(s.state.documents.Find(first)->selected_coins.size(),2);for(const auto& p:s.state.documents.Find(first)->coin_draft->inputs)IM_CHECK(pins.contains(a::CoinKey(p.outpoint)));const auto validate=[&](uint64_t id,bool expected){Press(ctx,s,"validate-pins");for(int i=0;i<40 && s.state.coin_controls.Owner(id).has_value()!=expected;++i){std::this_thread::sleep_for(std::chrono::milliseconds(1));ctx->Yield();}ctx->Yield(3);IM_CHECK(s.state.coin_controls.Owner(id).has_value()==expected);};validate(first,true);IM_CHECK(s.state.presentation.Snapshot().find("Funding service unavailable")!=std::string::npos);Press(ctx,s,"release-pins");IM_CHECK(!s.state.coin_controls.Owner(first));IM_CHECK_EQ(s.state.documents.Find(first)->selected_coins.size(),2);validate(first,true);Press(ctx,s,"show-coins");IM_CHECK_EQ(s.state.documents.ActiveId(),1);IM_CHECK_EQ(s.state.documents.Find(1)->coins.Selection(),pins);Press(ctx,s,"send-selected");const auto second=s.state.documents.ActiveId();IM_CHECK_EQ(second,3);Press(ctx,s,"validate-pins");for(int i=0;i<40 && s.state.coin_controls.DraftStatus(second).find("denied")==std::string::npos;++i){std::this_thread::sleep_for(std::chrono::milliseconds(1));ctx->Yield();}IM_CHECK(!s.state.coin_controls.Owner(second) && s.state.coin_controls.Owner(first));IM_CHECK(s.state.documents.Find(second)->coin_draft->inputs[0].current_reason.find("reservation")!=std::string::npos);const std::array<uint64_t,1> closed{first};IM_CHECK(s.state.documents.Close(closed));ctx->Yield(3);IM_CHECK(!s.state.coin_controls.Owner(first));validate(second,true);ConfirmClear(ctx,s);IM_CHECK(!s.state.documents.Find(second)->coin_draft && s.state.documents.Find(second)->selected_coins.empty() && !s.state.coin_controls.Owner(second));};
    t=make("clear_write_conflict_retains_pins_owner_and_visible_error");t->TestFunc=[](ImGuiTestContext* ctx){auto& s=ctx->GetVars<Fixture>();Ready(ctx,s);ctx->ItemClick(s.facts.coin.at("row-"+K(11)).id);ctx->Yield(3);Press(ctx,s,"send-selected");const auto id=s.state.documents.ActiveId();Press(ctx,s,"validate-pins");for(int i=0;i<40 && !s.state.coin_controls.Owner(id);++i){std::this_thread::sleep_for(std::chrono::milliseconds(1));ctx->Yield();}IM_CHECK(s.state.coin_controls.Owner(id));s.recovery_conflict=true;ctx->Yield(3);IM_CHECK(s.recovery_conflict_done);const auto revision=s.recovery_revision;ConfirmClear(ctx,s);IM_CHECK(s.state.documents.Find(id)->coin_draft && s.state.documents.Find(id)->selected_coins.size()==1 && s.state.coin_controls.Owner(id));IM_CHECK(s.state.presentation.Snapshot().find("metadata-conflict")!=std::string::npos);ctx->Yield(15);IM_CHECK_EQ(s.recovery_revision,revision);IM_CHECK(s.state.coin_controls.Owner(id));};
    t=make("public_pins_and_privacy_lock_do_not_restore_owner");t->TestFunc=[](ImGuiTestContext* ctx){auto& s=ctx->GetVars<Fixture>();Ready(ctx,s);ctx->ItemClick(s.facts.coin.at("row-"+K(11)).id);ctx->Yield(2);Press(ctx,s,"send-selected");const auto id=s.state.documents.ActiveId();Press(ctx,s,"validate-pins");for(int i=0;i<40 && !s.state.coin_controls.Owner(id);++i){std::this_thread::sleep_for(std::chrono::milliseconds(1));ctx->Yield();}IM_CHECK(s.state.coin_controls.Owner(id));s.lock=true;ctx->Yield(3);IM_CHECK(s.locked && s.recovery->Locked() && s.state.documents.Documents().empty() && !s.state.coin_controls.Owner(id));IM_CHECK(s.state.presentation.Snapshot().find(K(11))==std::string::npos);IM_CHECK(s.state.presentation.Tree().Validate());};
}
